        vm.assume(amount <= type(uint256).max);
        vm.deal(caller, amount);

        // Set initial balance via low-level store; only way without public setter
        // But we are forbidden from using vm.store. Instead, we can deposit via addToBalance.
        // If preBalance > 0, we need Ether. We assume the caller has enough Ether.
        vm.deal(caller, preBalance + amount);
