        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(caller);
        try c.addToBalance{value: amount}() {
        } catch {
        }

        uint256 balanceAfter = c.getBalance(caller);
        uint256 contractBalanceAfter = address(c).balance;

        // Invariant: balanceAfter <= balanceBefore + amount (no overflow)
        // This holds for reference but fails for mutant when overflow occurs.
        assertTrue(balanceAfter <= balanceBefore + amount);
    }
