pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();
        uint256 balance = c.getBalance(caller);
        // Check that the balance didn't overflow: if it did, balance * type(uint256).max would not equal balance.
        // On overflow, balance wraps around, making the multiplication produce a different result.
        bool invariantHolds = (balance == 0) ? true : (balance * type(uint256).max / type(uint256).max == balance);
        assertTrue(invariantHolds);
    }
}

